# 定义一个函数，用于判断是否为质数
def is_prime(n):
    # 质数必须大于等于2
    if n < 2:
        return False
    # 遍历从2到n的平方根，判断n是否能被其中的任意一个数整除
    for i in range(2, int(n**0.5)+1):
        if n % i == 0:
            return False
    return True

